from collections import deque

def comps(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   v=grid[r][c]
   if (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cc=[]
   while q:
    x,y=q.pop(); cc.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==v:
      seen.add((a,b));q.append((a,b))
   out.append((v,cc))
 return out
